import{_ as a,C as r,o,c as s,E as i,a2 as n}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"重建出的角色，不是权威来源","description":"","frontmatter":{"title":"重建出的角色，不是权威来源","date":"2026-08-31","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"上下文转换必须保留哪些权威事实，才能让下游智能体或权限审查器区分真实用户权威与被重建到高权限位置的低权限内容？","summary":"一项针对六种代码智能体运行框架的研究显示，低权限内容在上下文重建中被放入用户级位置后，可以绕过原本会拒绝常规危险指令的自动权限审查。更稳健的架构必须让原始主体、来源通道、权限等级与显式权限转换独立于重建后的消息角色。","sources":["research/analysis/Q-20260831-02-reconstructed-role-not-authority-provenance.md"],"item_id":"Q-20260831-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-31-a-reconstructed-role-is-not-proof-of-authority-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-08-31-a-reconstructed-role-is-not-proof-of-authority.md","filePath":"zh/industry/2026-08-31-a-reconstructed-role-is-not-proof-of-authority.md","lastUpdated":1788178493000}'),l={name:"zh/industry/2026-08-31-a-reconstructed-role-is-not-proof-of-authority.md"};function c(p,e,d,h,u,f){const t=r("ArticleCover");return o(),s("div",null,[i(t,{image:"/assets/covers/daily-2026-08-31-a-reconstructed-role-is-not-proof-of-authority-cover.png",kicker:"行业架构 · 每日研究",title:"重建出的角色，不是权威来源",summary:"一项针对六种代码智能体运行框架的研究显示，低权限内容在上下文重建中被放入用户级位置后，可以绕过原本会拒绝常规危险指令的自动权限审查。更稳健的架构必须让原始主体、来源通道、权限等级与显式权限转换独立于重建后的消息角色。",version:"Q-20260831-02",status:"Daily Runtime V5 · 2026-08-31",languageHref:"/en/industry/2026-08-31-a-reconstructed-role-is-not-proof-of-authority",languageLabel:"English"}),e[0]||(e[0]=n('<h1 id="重建出的角色-不是权威来源" tabindex="-1">重建出的角色，不是权威来源 <a class="header-anchor" href="#重建出的角色-不是权威来源" aria-label="Permalink to &quot;重建出的角色，不是权威来源&quot;">​</a></h1><p>一个自动权限审查器识别出命令具有危险性，却仍然批准执行。问题不一定是审查器看不懂风险，而可能是它相信命令来自用户：低权限工具内容经过持久化和上下文重建后，被放进了更强的消息位置。</p><p>文本没有变，权威含义却变了。对 Agent（智能体）运行框架而言，这不是普通的提示注入问题，而是权限来源在转换过程中丢失。重建后的 Role（消息角色）描述内容现在位于哪里，却不能证明最初是谁提供了它、它原本具有什么权限，以及中间是否发生过受信任的提升。</p><p>一项收录于 arXiv（开放预印本平台）的研究评估了六种代码智能体 Harness（运行框架）和 13 个攻击目标。研究给出的核心警告是：<strong>重建出的消息角色，不是充分的权威来源。原始主体、来源通道、权限等级和任何可信权限转换，必须在持久化、摘要、交接与重建全程保持可独立检查。</strong></p><h2 id="攻击改变的不是文本-而是有效权限" tabindex="-1">攻击改变的不是文本，而是有效权限 <a class="header-anchor" href="#攻击改变的不是文本-而是有效权限" aria-label="Permalink to &quot;攻击改变的不是文本，而是有效权限&quot;">​</a></h2><p>研究从工具或仓库控制的低权限内容出发，让运行框架将其持久化到目标、计划任务、技能式机制或历史中，再在后续上下文中重新引入。重建过程可以把原本来自工具的数据放进用户级、甚至系统有效的位置。</p><p>在报告的完全访问设置中，六种运行框架上的 13 个攻击目标全部成功。攻击覆盖机密性、完整性、可用性以及类似远程代码执行的效果。这里的共同机制不是某一句诱导文本特别强，而是运行框架在组装新上下文时改变了该文本的有效权限。</p><p>因此，序列化、摘要和 Prompt（提示上下文）组装并非中性的格式转换。只要它们能改变下游组件如何解释一条指令的权威，就属于控制面边界。</p><h2 id="风险审查不能修复错误的主体前提" tabindex="-1">风险审查不能修复错误的主体前提 <a class="header-anchor" href="#风险审查不能修复错误的主体前提" aria-label="Permalink to &quot;风险审查不能修复错误的主体前提&quot;">​</a></h2><p>研究还比较了支持自动权限审查的三种运行框架：Claude Code（代码智能体）、Codex（代码智能体）与 Qwen Code（代码智能体）。在上下文权限被提升的条件下，三者报告的 13 个目标全部成功；而没有这种上下文权限转换的常规提示注入或角色混淆比较为 0/13。</p><p>这个对照很重要。它说明自动审查器并不是对所有危险命令都无条件放行。它可以识别操作危险，却在错误的 Principal（权威主体）前提下作出决定：如果重建上下文把攻击者内容呈现为用户请求，审查器就可能认为“用户明知危险仍要求执行”。</p><p>内容风险审查回答“这项操作危险吗”；权威核验回答“有权要求这项操作的人真的提出了吗”。前一个问题不能替代后一个问题。让第二个 LLM（大语言模型）读取同一份已经丢失来源的上下文，也不能自动形成独立授权边界。</p><h2 id="权威来源必须独立于消息角色" tabindex="-1">权威来源必须独立于消息角色 <a class="header-anchor" href="#权威来源必须独立于消息角色" aria-label="Permalink to &quot;权威来源必须独立于消息角色&quot;">​</a></h2><p>一个最小的来源记录至少要回答四件事：原始主体是谁；内容通过什么通道进入；进入时的权限等级是什么；是否存在明确、可信、可审计的权限转换。</p><p>消息角色仍然有价值。它帮助模型理解对话结构和当前展示位置。但在经过有损转换后，角色只能表达“现在怎样呈现”，不能单独证明“最初拥有什么权威”。</p><p>因此，高影响行动的授权门禁不应只读取最终提示上下文。它还应读取独立来源元数据，并核验任何权限提升是否由可信组件显式作出。来源未知或丢失时，正确状态是权威缺陷，而不是在组装时赋予更强角色来补齐空白。</p><h2 id="持久化与交接也是权限边界" tabindex="-1">持久化与交接也是权限边界 <a class="header-anchor" href="#持久化与交接也是权限边界" aria-label="Permalink to &quot;持久化与交接也是权限边界&quot;">​</a></h2><p>研究覆盖目标、计划任务和技能式持久化路径。这把问题从即时对话扩展到长期运行：今天写入的一段低权限内容，可能在明天的计划任务中以更强位置重新出现。</p><p>摘要压缩、持久化、计划重载与任务交接都会合并、裁剪或重排信息。只要来源证据没有同步保存，内容就可能在下一次恢复时获得它从未拥有的权威。</p><p>受治理系统应把这些环节作为来源保持门禁。每次转换都要么保留原始权限，要么记录显式升级；不能让升级成为序列化格式或上下文模板的副作用。</p><h2 id="显式采纳与永久污染都不是答案" tabindex="-1">显式采纳与永久污染都不是答案 <a class="header-anchor" href="#显式采纳与永久污染都不是答案" aria-label="Permalink to &quot;显式采纳与永久污染都不是答案&quot;">​</a></h2><p>来源感知并不意味着低权限内容永远不能被可信用户采纳。用户可以引用工具结果、接受建议或明确提升某条指令。关键是，这种采纳应形成新的、可审计的权限转换证据，而不是靠内容随后出现在用户消息区域来推断。</p><p>同样，多个来源被合并时，系统不能简单选取最高权限，也不能把全部派生内容永久标记为最低权限。需要声明合成规则：哪些片段来自哪些主体，谁对最终综合结果负责，以及提升是否覆盖全部内容还是仅覆盖特定命题。</p><h2 id="证据边界与未决问题" tabindex="-1">证据边界与未决问题 <a class="header-anchor" href="#证据边界与未决问题" aria-label="Permalink to &quot;证据边界与未决问题&quot;">​</a></h2><p>研究覆盖六种代码智能体运行框架和特定上下文构造机制，并不代表所有智能体系统都存在相同实现，也没有证明签名信封、能力记录或类型化来源图中的哪一种方案最优。实验成功率也不能直接推算真实组织的发生率和影响范围。</p><p>但架构边界已经足够清楚：<strong>重建角色只能描述展示位置；行动权威必须追溯到原始主体及受治理的权限转换。若高影响决定所需来源已经丢失，系统应拒绝推断更强权威。</strong></p><p>接下来仍需确定：最小来源元组包含哪些字段；多个片段合并时怎样组合来源；哪些组件可以提升权限；旧的无类型上下文如何迁移而不静默授权。</p><p><strong>一手证据：</strong> <a href="https://arxiv.org/abs/2608.27299" target="_blank" rel="noreferrer">上下文获得根权限：大语言模型运行框架中的权限提升</a></p>',28))])}const y=a(l,[["render",c]]);export{m as __pageData,y as default};
